    save_button = page.get_by_role("button", name="save")
    if await save_button.count() == 0:
        save_button = page.get_by_role("button", name="Save")
    if await save_button.count() == 0:
        # Use filter with has_text to find a button with 'Save' text.
        save_button = page.get_by_role("button").filter(has_text="Save")
    if await save_button.count() == 0:
        raise Exception("Save button not found.")
    await save_button.click()
    # Wait for save to complete.
    await page.wait_for_load_state("networkidle")
    await asyncio.sleep(2)  # Additional wait to ensure changes are applied.

    # Verify the price was updated by checking the field again.
    updated_price = await price_field.input_value()
    return updated_price
